import json
from src.nodes.base import BaseNode
from src.runtime.layout_realization import get_layout_application_engine, ResolvedTransform

class Hou_Mcp_Apply_Layout(BaseNode):
    name = "hou_mcp_apply_layout"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("transforms_json",    "string", widget_type="text", default="[]")
        self.add_input("node_path_map_json", "string", widget_type="text", default="{}")
        self.add_output("result_json")
        self.add_output("applied", "int")
        self.add_output("skipped", "int")
        self.add_output("failed",  "int")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        raw_t = (inputs.get("transforms_json")    or "").strip()
        raw_m = (inputs.get("node_path_map_json") or "").strip()

        try:
            raw_list      = json.loads(raw_t) if raw_t else []
            transforms    = [ResolvedTransform.from_dict(t) for t in raw_list]
            node_path_map = json.loads(raw_m) if raw_m else {}
        except Exception:
            self.log_error("Input JSON is not valid.")
            return {"result_json": "{}", "applied": 0, "skipped": 0, "failed": 0, "exec_out": True}

        try:
            result = get_layout_application_engine().apply_layout(transforms, node_path_map)
            return {
                "result_json": json.dumps(result.to_dict(), sort_keys=True, indent=2),
                "applied":     result.applied,
                "skipped":     result.skipped,
                "failed":      result.failed,
                "exec_out":    True,
            }
        except Exception as exc:
            self.log_error(f"Layout application failed: {exc}")
            return {"result_json": "{}", "applied": 0, "skipped": 0, "failed": 0, "exec_out": True}

def register_node():
    return Hou_Mcp_Apply_Layout
